205	int run_fast(const Cli& cli) {
206	  // fast is QEMU-only for the built-in qemu64/qemu32. A vsim (cycle-accurate)
207	  // engine is ALSO accepted here: fast then runs the built-in QEMU carrying
208	  // that engine's geometry -- `-cpu <model>,vlen=N` plus `-readconfig <cfg>`
209	  // (the engine's ISA globals AND its HVM window's hvm_size_pow_2, so
210	  // 0x90000000 is backed at the engine's size). This lets an HVM-using workload
211	  // run functionally, end-to-end, under fast (no cycle-accurate leg) -- the
212	  // clean way to check HVM correctness before paying for a hybrid/cycle run.
213	  const bool explicit_qemu =
214	      cli.engine == kQemuId64 || cli.engine == kQemuId32;
215	  const EngineDescriptor* vsim_eng = nullptr;
216	  Discovery disc;  // kept alive: vsim_eng points into disc.engines
217	  QemuCfgSync cfg_sync;
218	  if (!cli.engine.empty() && !explicit_qemu) {
219	    disc = discover_engines();
220	    vsim_eng = resolve_accurate_engine_or_report(disc, cli.engine,
221	                                                 "andesim run --mode fast");
222	    if (!vsim_eng) return 2;
223	    // fast execs QEMU (no post-exec cleanup), so stage the cfg at a FIXED cache
224	    // path (overwritten per run) instead of a mkdtemp that would leak per run.
225	    const std::string cache = andesim_cache_dir();
226	    if (cache.empty()) {
227	      std::fprintf(stderr,
228	                   "andesim run --mode fast: no cache dir to stage the engine "
229	                   "cfg (set HOME or XDG_CACHE_HOME)\n");
230	      return 2;
231	    }
232	    const std::string cfg_wd = cache + "/fast";
233	    std::error_code ec;
234	    fs::create_directories(cfg_wd, ec);
235	    cfg_sync = sync_qemu_cfg(vsim_eng->bin_path, cfg_wd);
236	    if (cfg_sync.cfg_path.empty()) {
237	      std::fprintf(stderr,
238	                   "andesim run --mode fast: engine '%s' has no "
239	                   "--print-qemu-config; cannot derive its HVM/VLEN geometry\n",
240	                   cli.engine.c_str());
241	      return 2;
242	    }
243	  }
244	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
245	  // (the app + vlinux's own arenas) when the user did not pick one.
246	  std::string mem_size_spec = cli.mem_size;
247	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
248	
249	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
250	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
251	  std::string err;
252	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
253	  if (!err.empty()) {
254	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
255	    return 2;
256	  }
257	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
258	  if (cli.gdb) {
259	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
260	    extra.push_back("-gdb");
261	    extra.push_back("tcp::" + port);
262	    extra.push_back("-S");
263	  }
264	
265	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
266	  // the proxy kernel. The ELF positional is the APP, not the boot image --
267	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
268	  Cli cli2 = cli;
269	  std::string boot_elf;
270	  if (cli.runtime == "linux") {
271	    if (int rc = check_one_elf(cli, "fast")) return rc;
272	    const std::string app_elf =
273	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
274	    if (app_elf.empty()) return 2;
275	
276	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
277	    // strictly tighter validation than parse_size alone), so this call
278	    // cannot fail: reused only to get the byte count for the manifest.
279	    const long long mem_bytes = parse_size(mem_size_spec, err);
280	
281	    boot_elf = stage_linux_boot(app_elf, static_cast<uint64_t>(mem_bytes),
282	                                cli.passthrough,
283	                                "andesim run --mode fast --runtime linux");
284	    if (boot_elf.empty()) return 2;
285	
286	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
287	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
288	    // engine flags (e.g. "-m x.gguf" is not a memory size).
289	    cli2.passthrough.clear();
290	
291	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
292	    // measurement targets, not the ax46 vplat default (last -cpu wins). With a
293	    // vsim engine the -cpu comes from its synced geometry (pushed below,
294	    // alongside -readconfig); only the plain-QEMU path pins the ax45 default.
295	    if (!vsim_eng) {
296	      extra.push_back("-cpu");
297	      extra.push_back("andes-ax45mpv,vlen=512");
298	    }
299	  }
300	
301	  // A vsim engine: append its synced -cpu (model + vlen) and -readconfig (ISA
302	  // globals + HVM window). Pushed after any template/linux default so the
303	  // engine's -cpu wins the "last -cpu wins" rule.
304	  if (vsim_eng) {
305	    const std::vector<std::string> geo =
