int run_fast(const Cli& cli) {
  // fast is QEMU-only for the built-in qemu64/qemu32. A vsim (cycle-accurate)
  // engine is ALSO accepted here: fast then runs the built-in QEMU carrying
  // that engine's geometry -- `-cpu <model>,vlen=N` plus `-readconfig <cfg>`
  // (the engine's ISA globals AND its HVM window's hvm_size_pow_2, so
  // 0x90000000 is backed at the engine's size). This lets an HVM-using workload
  // run functionally, end-to-end, under fast (no cycle-accurate leg) -- the
  // clean way to check HVM correctness before paying for a hybrid/cycle run.
  const bool explicit_qemu =
      cli.engine == kQemuId64 || cli.engine == kQemuId32;
  const EngineDescriptor* vsim_eng = nullptr;
  Discovery disc;  // kept alive: vsim_eng points into disc.engines
  QemuCfgSync cfg_sync;
  if (!cli.engine.empty() && !explicit_qemu) {
    disc = discover_engines();
    vsim_eng = resolve_accurate_engine_or_report(disc, cli.engine,
                                                 "andesim run --mode fast");
    if (!vsim_eng) return 2;
    // fast execs QEMU (no post-exec cleanup), so stage the cfg at a FIXED cache
    // path (overwritten per run) instead of a mkdtemp that would leak per run.
    const std::string cache = andesim_cache_dir();
    if (cache.empty()) {
      std::fprintf(stderr,
                   "andesim run --mode fast: no cache dir to stage the engine "
                   "cfg (set HOME or XDG_CACHE_HOME)\n");
      return 2;
    }
    const std::string cfg_wd = cache + "/fast";
    std::error_code ec;
    fs::create_directories(cfg_wd, ec);
    cfg_sync = sync_qemu_cfg(vsim_eng->bin_path, cfg_wd);
    if (cfg_sync.cfg_path.empty()) {
      std::fprintf(stderr,
                   "andesim run --mode fast: engine '%s' has no "
                   "--print-qemu-config; cannot derive its HVM/VLEN geometry\n",
                   cli.engine.c_str());
      return 2;
    }
  }
  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
  // (the app + vlinux's own arenas) when the user did not pick one.
  std::string mem_size_spec = cli.mem_size;
  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";

  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
  // default injected). It precedes the post-`--` args, so a user's own -m wins.
  std::string err;
  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
    return 2;
  }
  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
  if (cli.gdb) {
    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
    extra.push_back("-gdb");
    extra.push_back("tcp::" + port);
    extra.push_back("-S");
  }

  // --runtime linux: stage a manifested vlinux.elf that boots the app under
  // the proxy kernel. The ELF positional is the APP, not the boot image --
  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
  Cli cli2 = cli;
  std::string boot_elf;
  if (cli.runtime == "linux") {
    if (int rc = check_one_elf(cli, "fast")) return rc;
    const std::string app_elf =
        abs_elf(cli.positional[0], "--mode fast --runtime linux");
    if (app_elf.empty()) return 2;

    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
    // strictly tighter validation than parse_size alone), so this call
    // cannot fail: reused only to get the byte count for the manifest.
    const long long mem_bytes = parse_size(mem_size_spec, err);

    boot_elf = stage_linux_boot(app_elf, static_cast<uint64_t>(mem_bytes),
                                cli.passthrough,
                                "andesim run --mode fast --runtime linux");
    if (boot_elf.empty()) return 2;

    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
    // engine flags (e.g. "-m x.gguf" is not a memory size).
    cli2.passthrough.clear();

    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
    // measurement targets, not the ax46 vplat default (last -cpu wins). With a
    // vsim engine the -cpu comes from its synced geometry (pushed below,
    // alongside -readconfig); only the plain-QEMU path pins the ax45 default.
    if (!vsim_eng) {
      extra.push_back("-cpu");
      extra.push_back("andes-ax45mpv,vlen=512");
    }
  }

  // A vsim engine: append its synced -cpu (model + vlen) and -readconfig (ISA
  // globals + HVM window). Pushed after any template/linux default so the
  // engine's -cpu wins the "last -cpu wins" rule.
  if (vsim_eng) {
    const std::vector<std::string> geo =
        fast_engine_qemu_extras(cfg_sync.cpu, vsim_eng->vlen, cfg_sync.cfg_path);
    extra.insert(extra.end(), geo.begin(), geo.end());
  }

  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
  // ELF -- the override is the user's call.
  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
  int xlen;
  if (vsim_eng) xlen = 64;  // the wired vsim engines are all rv64
  else if (cli.engine == kQemuId32) xlen = 32;
  else if (cli.engine == kQemuId64) xlen = 64;
  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
  // Only an explicit engine can disagree with the ELF (when none is given, xlen
  // == elf_w), so this guard already implies an explicit --engine.
  if (elf_w && elf_w != xlen)
    std::fprintf(stderr,
                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
